-- composition of rule kernels L:decorrelate_predicate_subquery x L:eliminate_outer_join (datafusion), template product
SELECT count(*) FROM (WITH cte1 AS (SELECT DISTINCT (-1) AS c0, (1.0 / 3)::float8 AS c1 FROM t2 AS a1 WHERE (NOT EXISTS (SELECT 7 AS c0, 1.0::float8 AS c1))) SELECT 1.5::numeric AS c0, FALSE AS c1 FROM t2 AS a2 WHERE (('2024-12-31'::date = '2000-01-01'::date) OR ((ABS (3))::bigint >= LEAST (10::bigint, (SELECT COUNT (*) FROM cte1 AS a3))))) AS ka CROSS JOIN (WITH cte1 AS (SELECT DISTINCT ROUND ((42.5::numeric - NULL::numeric), 2) AS c0, a1.n AS c1, '_'::text AS c2 FROM (v0 AS a1 FULL JOIN t1 AS a2 ON (a1.c0 = a2.c0)) WHERE (FALSE <= (a2.c0 BETWEEN 2 AND 3))) SELECT a3.c0 AS c0, 'a'::text AS c1, (CASE WHEN FALSE THEN '7 days'::interval ELSE GREATEST ('7 days'::interval, (SELECT MIN ('1 day'::interval) FROM cte1 AS a4 WHERE TRUE)) END + '1 year 2 months 3 days 4 hours 5 minutes 6.789 seconds'::interval) AS c2 FROM generate_series (5, 10) AS a3 (c0)) AS kb;
